import { useCallback, useEffect, useMemo, useState } from "react";
import { ipc, isTauriRuntime, pickFolder, pickMarkdownFile } from "../lib/ipc";
import { supportsDirectoryPicker } from "../lib/browserFs";
import type { FileEntry, WorkspaceDescriptor } from "../contracts/types";

function parentRel(dir: string): string {
  if (!dir) return "";
  const i = dir.lastIndexOf("/");
  return i <= 0 ? "" : dir.slice(0, i);
}

export function FileExplorer(props: {
  workspace: WorkspaceDescriptor | null;
  onOpenRelative: (path: string) => void;
  onOpenFolder: (absolutePath: string) => Promise<unknown>;
  onOpenFile: (absolutePath: string) => Promise<unknown>;
  onWorkspaceReady: () => Promise<unknown>;
  query: string;
  onQuery: (q: string) => void;
  activePath: string;
}) {
  const [entries, setEntries] = useState<FileEntry[]>([]);
  const [cwd, setCwd] = useState(""); // relative dir inside workspace
  const [busy, setBusy] = useState(false);
  const [hint, setHint] = useState<string | null>(null);
  const tauri = isTauriRuntime();
  const canPickDir = tauri || supportsDirectoryPicker();

  const refresh = useCallback(
    async (ws: WorkspaceDescriptor, dir: string) => {
      try {
        const list = await ipc.listEntries(ws.id, dir);
        setEntries(list);
      } catch (e) {
        setEntries([]);
        setHint(e instanceof Error ? e.message : "Falha ao listar pasta");
      }
    },
    [],
  );

  useEffect(() => {
    if (props.workspace) {
      setCwd("");
      void refresh(props.workspace, "");
      setHint(null);
    } else {
      setEntries([]);
      setCwd("");
    }
  }, [props.workspace, refresh]);

  useEffect(() => {
    if (props.workspace) {
      void refresh(props.workspace, cwd);
    }
  }, [cwd, props.workspace, refresh]);

  const crumbs = useMemo(() => {
    if (!cwd) return [] as string[];
    return cwd.split("/").filter(Boolean);
  }, [cwd]);

  const handleOpenFolder = async () => {
    setBusy(true);
    setHint(null);
    try {
      const result = await pickFolder();
      if (!result.ok) {
        setHint(result.reason === "cancel" ? "Seleção cancelada." : "Seu browser não suporta escolher pasta.");
        return;
      }
      // browser-fs: handle already stored; pathOrLabel is label
      // tauri: absolute path
      // demo: label
      if (result.source === "tauri") {
        await props.onOpenFolder(result.pathOrLabel);
      } else {
        await props.onWorkspaceReady();
      }
      setCwd("");
      if (result.source === "demo") {
        setHint("Demo local (sem API de pasta). No Chrome/Edge use Abrir pasta para o disco real.");
      } else if (result.source === "browser-fs") {
        setHint(`Pasta real: ${result.pathOrLabel}. Clique nas pastas 📂 para entrar.`);
      }
    } catch (e) {
      setHint(e instanceof Error ? e.message : "Erro ao abrir pasta");
    } finally {
      setBusy(false);
    }
  };

  const handleOpenFile = async () => {
    setBusy(true);
    setHint(null);
    try {
      const result = await pickMarkdownFile();
      if (!result.ok) {
        setHint(result.reason === "cancel" ? "Seleção cancelada." : "Não foi possível abrir o arquivo.");
        return;
      }
      if (result.source === "tauri") {
        await props.onOpenFile(result.pathOrLabel);
      } else {
        await props.onWorkspaceReady();
        // open first/root file name
        const name = result.pathOrLabel.includes("/")
          ? result.pathOrLabel.split("/").pop()!
          : result.pathOrLabel;
        // for single file browser pick, relative is the file name
        props.onOpenRelative(name === "demo-workspace" ? "README.md" : name);
      }
      setCwd("");
    } catch (e) {
      setHint(e instanceof Error ? e.message : "Erro ao abrir arquivo");
    } finally {
      setBusy(false);
    }
  };

  const onEntryClick = (e: FileEntry) => {
    if (e.kind === "dir") {
      setCwd(e.relativePath);
      return;
    }
    props.onOpenRelative(e.relativePath);
  };

  const filtered = entries.filter(
    (e) => !props.query || e.name.toLowerCase().includes(props.query.toLowerCase()),
  );

  return (
    <div className="file-explorer">
      <div className="panel-header">
        <h2>Arquivos</h2>
        {props.workspace && (
          <span className="workspace-badge" title={props.workspace.rootLabel}>
            {props.workspace.rootLabel}
          </span>
        )}
      </div>

      <div className="open-actions">
        <button
          type="button"
          className="btn btn-primary"
          onClick={() => void handleOpenFolder()}
          disabled={busy}
          aria-label="Abrir pasta"
        >
          <span className="btn-icon" aria-hidden>
            📁
          </span>
          Abrir pasta
        </button>
        <button
          type="button"
          className="btn btn-secondary"
          onClick={() => void handleOpenFile()}
          disabled={busy}
          aria-label="Abrir arquivo Markdown"
        >
          <span className="btn-icon" aria-hidden>
            📄
          </span>
          Abrir arquivo
        </button>
      </div>

      {!tauri && (
        <p className="banner banner-info" role="status">
          {canPickDir ? (
            <>
              No <strong>Chrome/Edge</strong>, <strong>Abrir pasta</strong> usa o seletor real do
              sistema — você navega nas pastas do disco. Depois, use a lista abaixo para entrar em
              subpastas.
            </>
          ) : (
            <>
              Este browser não expõe seletor de pasta. Use Chrome/Edge, ou o app nativo:{" "}
              <code>pnpm tauri dev</code>.
            </>
          )}
        </p>
      )}

      {props.workspace && (
        <nav className="breadcrumb" aria-label="Caminho na pasta">
          <button
            type="button"
            className="crumb"
            onClick={() => setCwd("")}
            disabled={!cwd}
            title="Raiz do workspace"
          >
            /
          </button>
          {crumbs.map((part, idx) => {
            const path = crumbs.slice(0, idx + 1).join("/");
            const isLast = idx === crumbs.length - 1;
            return (
              <span key={path} className="crumb-wrap">
                <span className="crumb-sep">/</span>
                <button
                  type="button"
                  className={"crumb" + (isLast ? " is-current" : "")}
                  onClick={() => setCwd(path)}
                  disabled={isLast}
                >
                  {part}
                </button>
              </span>
            );
          })}
          {cwd && (
            <button
              type="button"
              className="btn btn-secondary btn-sm crumb-up"
              onClick={() => setCwd(parentRel(cwd))}
              aria-label="Pasta superior"
            >
              ↑ Subir
            </button>
          )}
        </nav>
      )}

      <label className="field">
        <span>Filtrar nesta pasta</span>
        <input
          aria-label="Filtrar arquivos na pasta atual"
          placeholder="Filtrar arquivos…"
          value={props.query}
          onChange={(e) => props.onQuery(e.target.value)}
        />
      </label>

      {hint && (
        <p className="banner banner-muted" role="status">
          {hint}
        </p>
      )}

      <div className="file-list-wrap">
        {!props.workspace && (
          <div className="empty-state">
            <p>Nenhuma pasta aberta</p>
            <p className="muted">Use <strong>Abrir pasta</strong> e navegue até o arquivo.</p>
          </div>
        )}
        {props.workspace && filtered.length === 0 && (
          <div className="empty-state">
            <p>Pasta vazia ou sem correspondências</p>
            {cwd && (
              <button type="button" className="btn btn-secondary btn-sm" onClick={() => setCwd(parentRel(cwd))}>
                Voltar
              </button>
            )}
          </div>
        )}
        <ul className="file-list">
          {cwd && (
            <li>
              <button type="button" className="file-item" onClick={() => setCwd(parentRel(cwd))}>
                <span className="file-icon" aria-hidden>
                  ↩️
                </span>
                <span className="file-name">..</span>
              </button>
            </li>
          )}
          {filtered.map((e) => (
            <li key={e.relativePath}>
              <button
                type="button"
                className={
                  "file-item" +
                  (props.activePath === e.relativePath ? " is-active" : "") +
                  (e.kind === "dir" ? " is-dir" : "")
                }
                onClick={() => onEntryClick(e)}
              >
                <span className="file-icon" aria-hidden>
                  {e.kind === "dir" ? "📂" : "📝"}
                </span>
                <span className="file-name">{e.name}</span>
                {e.kind === "dir" && <span className="file-meta">abrir</span>}
              </button>
            </li>
          ))}
        </ul>
      </div>
    </div>
  );
}
